using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, B;
    cin >> n >> B;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    vector<int> diffList;
    int evenCount = 0, oddCount = 0;
    for (int i = 0; i < n - 1; i++) {
        if ((a[i] & 1) == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
        if (evenCount == oddCount) {
            diffList.push_back(abs(a[i] - a[i + 1]));
        }
    }
    std::sort(diffList.begin(), diffList.end());
    int used = 0;
    for (int diff : diffList) {
        if (diff <= B) {
            B -= diff;
            used++;
        } else {
            break;
        }
    }
    cout << used << "\n";
    return 0;
}
